def is_nested(string):
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if len(stack) > 1 and stack[-2] == '[':
                return True
            if not stack or stack[-1] != '[':
                return False
            else:
                stack.pop()
